@Test
public void test_ExtractDuration_happyPath() {
    RangerTimeOfDayMatcher matcher = new RangerTimeOfDayMatcher();
    Object[][] input = new Object[][] { { "9am-5pm", true, 9 * 60, (12 + 5) * 60 }, { "1 PM - 10P.M.", true, (12 + 1) * 60, (12 + 10) * 60 }, { "1PM - 9AM", true, (12 + 1) * 60, 9 * 60 }, { "11am-12pm", true, 11 * 60, 12 * 60 }, { "11pm-12am", true, (12 + 11) * 60, 0 * 60 }, { "12am-12pm", true, 0 * 60, 12 * 60 }, { "12pm-12am", true, 12 * 60, 0 * 60 }, // illegal patterns should come back as null, too
    { "1PM", false, null, null } };
    for (Object[] data : input) {
        int[] duration = matcher.extractDuration((String) data[0]);
        boolean expectedToMatch = (boolean) data[1];
        if (expectedToMatch) {
            int start = (Integer) data[2];
            int end = (Integer) data[3];
            assertArrayEquals(new int[] { start, end }, duration);
        } else {
            assertNull(duration);
        }
    }
}

@Test
public void test_durationsMatched() {
    List<int[]> durations = Lists.newArrayList(// 2am-7am
    new int[] { 2 * 60, 7 * 60 }, // 9am-5pm
    new int[] { 9 * 60, 17 * 60 });
    RangerTimeOfDayMatcher matcher = new RangerTimeOfDayMatcher();
    Object[][] input = new Object[][] { { 1, false }, { 2, true }, { 3, true }, { 7, true }, { 8, false }, { 9, true }, { 10, true }, { 16, true }, { 17, true }, { 18, false }, { 23, false } };
    for (Object[] data : input) {
        int hour = (int) data[0];
        boolean matchExpected = (boolean) data[1];
        boolean result = matcher.durationMatched(durations, hour, 0);
        if (matchExpected) {
            assertTrue("" + hour, result);
        } else {
            assertFalse("" + hour, result);
        }
    }
}

@Test
public void test_end2end_happyPath() {
    RangerPolicyItemCondition itemCondition = mock(RangerPolicyItemCondition.class);
    when(itemCondition.getValues()).thenReturn(Arrays.asList("2:45a.m. -7:00 AM", "  9:15AM- 5:30P.M. ", "11pm-2am"));
    RangerTimeOfDayMatcher matcher = new RangerTimeOfDayMatcher();
    matcher.setConditionDef(null);
    matcher.setPolicyItemCondition(itemCondition);
    matcher.init();
    Object[][] input = new Object[][] { { 1, 0, true }, { 2, 0, true }, { 2, 1, false }, { 2, 44, false }, { 2, 45, true }, { 3, 0, true }, { 7, 0, true }, { 7, 01, false }, { 8, 0, false }, { 9, 15, true }, { 10, 0, true }, { 17, 0, true }, { 17, 30, true }, { 17, 31, false }, { 18, 0, false }, { 22, 59, false }, { 23, 0, true } };
    RangerAccessRequest request = mock(RangerAccessRequest.class);
    for (Object[] data : input) {
        int hour = (int) data[0];
        int minute = (int) data[1];
        Calendar c = new GregorianCalendar(2015, Calendar.APRIL, 1, hour, minute);
        Date aDate = c.getTime();
        when(request.getAccessTime()).thenReturn(aDate);
        boolean matchExpected = (boolean) data[2];
        if (matchExpected) {
            assertTrue("" + hour, matcher.isMatched(request));
        } else {
            assertFalse("" + hour, matcher.isMatched(request));
        }
    }
}

