    props.put(basePropName + "." + AuditQueue.PROP_BATCH_SIZE, "" + batchSize);
    props.put(basePropName + "." + AuditQueue.PROP_QUEUE_SIZE, "" + queueSize);
    props.put(basePropName + "." + AuditQueue.PROP_BATCH_INTERVAL, "" + intervalMS);
