    props.put(basePropName + "." + BaseAuditHandler.PROP_NAME, "testAuditBatchQueueDestDownRestart_" + MiscUtil.generateUniqueId());
    props.put(basePropName + "." + AuditQueue.PROP_BATCH_SIZE, "" + batchSize);
